#!/usr/bin/env node
/**
 * The committed world content is what the builder produces, covers every room,
 * and asks the viewer only for things it can draw.
 *
 * `src/data/world/` is a derived artefact the way `src/data/map/` is: 86 files,
 * one per zone plus an index, generated by `tools/build-world-content.mjs` and
 * committed so the app can import a zone without running a build step. A
 * derived file that is committed is a file somebody will eventually hand-edit,
 * and the edit will look exactly like a rule change that nobody made. So:
 *
 *   1. re-running the builder reproduces every byte of it;
 *   2. every room in `src/data/map/` has a content entry, counted N of N;
 *   3. every primitive kind the content asks for is one a factory is
 *      registered for — the set read out of `godot/scripts/shared_asset_content.gd`
 *      rather than typed here, so a kind renamed in GDScript takes this red;
 *   4. the unknown share is under the ceiling the builder publishes;
 *   5. the vocabularies are total: every ground kind maps to a block kind,
 *      every block kind is one of the four, every rule named in a record is one
 *      of the declared rules.
 *
 * Every count is asserted against a floor as well as a property. "No room is
 * missing its content entry" is true, and empty, of a run that read no rooms —
 * the same defect `tools/build-world-content.mjs` guards its own input with.
 *
 *   node --experimental-strip-types tools/world-content-test.mjs
 *
 * `--experimental-strip-types` because the builder it shells out to imports
 * `src/lib/mapLandmarks.ts`.
 */
import { execFileSync } from 'node:child_process'
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  BLOCK_KINDS,
  GROUND_KINDS,
  GROUND_RULES,
  blockKindFor,
  primitivesFor,
} from '../src/lib/world-content-rules.mjs'

const MAP_DIR = 'src/data/map'
const WORLD_DIR = 'src/data/world'
const CONTENT_PACK = 'godot/scripts/shared_asset_content.gd'

/**
 * Floors, not comments.
 *
 * `src/lib/mapData.ts` states 17,750 rooms in 85 zones and
 * `tools/map-data-test.mjs` holds it to that; these sit well below, so they
 * catch an empty or half-copied data directory without needing to be touched
 * when the map is rebuilt. Without them, "every room has an entry" and "no kind
 * is undrawable" are both true of zero rooms, which is the most reassuring
 * output this file can produce and means nothing.
 */
const MIN_ROOMS = 15000
const MIN_ZONES = 60
const MIN_REGISTERED_KINDS = 4

let pass = 0
let fail = 0
const ok = (what, cond, detail = '') => {
  if (cond) {
    pass += 1
    console.log(`OK   ${what.padEnd(72)} ${detail}`)
  } else {
    fail += 1
    console.log(`FAIL ${what.padEnd(72)} ${detail}`)
  }
}

// ------------------------------------------------------- 1. no drift

let checkOutput = ''
let checkFailed = false
try {
  checkOutput = execFileSync(
    process.execPath,
    ['--experimental-strip-types', 'tools/build-world-content.mjs', '--check'],
    { encoding: 'utf8' }
  )
} catch (error) {
  checkFailed = true
  checkOutput = `${error.stdout ?? ''}${error.stderr ?? ''}`
}
const checkedFiles = Number(/OK\s+(\d+) generated files match/.exec(checkOutput)?.[1] ?? 0)
ok(
  'the committed content is byte-for-byte what the builder produces',
  !checkFailed && checkedFiles >= MIN_ZONES,
  checkFailed
    ? `builder --check exited non-zero: ${checkOutput.split('\n').find((line) => line.startsWith('FAIL')) ?? 'no FAIL line'}`
    : `${checkedFiles} files compared, floor ${MIN_ZONES}`
)

// ------------------------------------------------------ 2. coverage

const mapZones = readdirSync(MAP_DIR)
  .filter((name) => name.endsWith('.json') && name !== 'index.json')
  .map((name) => JSON.parse(readFileSync(join(MAP_DIR, name), 'utf8')))
const index = JSON.parse(readFileSync(join(WORLD_DIR, 'index.json'), 'utf8'))

let mapRooms = 0
let matched = 0
let missingZones = 0
const missingExamples = []
for (const zone of mapZones) {
  let content = null
  try {
    content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  } catch {
    missingZones += 1
    continue
  }
  const byId = new Map(content.rooms.map((room) => [room.id, room]))
  for (const room of zone.rooms ?? []) {
    mapRooms += 1
    if (byId.has(room.id)) matched += 1
    else if (missingExamples.length < 5) missingExamples.push(`${zone.id}-${room.id}`)
  }
}

ok(
  'the map itself is all there, so the counts below mean something',
  mapRooms >= MIN_ROOMS && mapZones.length >= MIN_ZONES,
  `${mapRooms} rooms in ${mapZones.length} zones, floors ${MIN_ROOMS}/${MIN_ZONES}`
)
ok(
  'every room in every zone has a content entry',
  matched === mapRooms && missingZones === 0,
  `${matched} of ${mapRooms}${missingZones ? `, ${missingZones} zones have no content file` : ''}${missingExamples.length ? `, e.g. ${missingExamples.join(' ')}` : ''}`
)
ok(
  "and the index agrees with what the zone files hold, so it cannot flatter",
  index.counts.rooms === mapRooms && index.counts.zones === mapZones.length,
  `index says ${index.counts.rooms} rooms in ${index.counts.zones} zones`
)

// ------------------------------------- 3. only kinds the viewer can draw

/**
 * The registered set, read out of the content pack rather than typed here.
 *
 * `ensure_registration()` is the one function that hands a factory to
 * `ContentRegistry`, so every `ContentRegistry.register("<kind>", …)` line in
 * it is a kind the viewer can actually draw. A hand-written copy of that list
 * would agree with GDScript by coincidence, which is exactly the class of
 * defect `tools/board-geometry-drift-test.mjs` exists for.
 */
const packSource = readFileSync(CONTENT_PACK, 'utf8')
const registered = new Set(
  [...packSource.matchAll(/ContentRegistry\.register\(\s*"([^"]+)"/g)].map((match) => match[1])
)
ok(
  'the Godot content pack still declares a registry of kinds this can read',
  registered.size >= MIN_REGISTERED_KINDS,
  `${registered.size} kinds registered in ${CONTENT_PACK}: ${[...registered].sort().join(', ')} (floor ${MIN_REGISTERED_KINDS})`
)

let primitivesAsked = 0
const undrawable = new Map()
const groundSeen = new Set()
const ruleSeen = new Set()
let blockAgrees = 0
let contentRooms = 0
for (const zone of mapZones) {
  const content = JSON.parse(readFileSync(join(WORLD_DIR, `${zone.id}.json`), 'utf8'))
  for (const room of content.rooms) {
    contentRooms += 1
    groundSeen.add(room.ground)
    ruleSeen.add(room.rule)
    if (blockKindFor(room.ground) === room.block) blockAgrees += 1
    for (const primitive of primitivesFor({
      blockKind: room.block,
      tags: room.classification.tags,
      boundaryEdges: room.boundaryEdges,
    })) {
      primitivesAsked += 1
      if (!registered.has(primitive.kind)) {
        undrawable.set(primitive.kind, (undrawable.get(primitive.kind) ?? 0) + 1)
      }
    }
  }
}
ok(
  'every primitive the content asks for has a factory registered in Godot',
  undrawable.size === 0 && primitivesAsked >= MIN_ROOMS,
  undrawable.size
    ? `${primitivesAsked} asked for; unregistered: ${[...undrawable].map(([kind, n]) => `${kind} x${n}`).join(', ')}`
    : `${primitivesAsked} primitives asked for across ${contentRooms} rooms, all registered`
)

// -------------------------------------------------- 4. the unknown ceiling

// Read out of the published index, not imported from the builder: the builder
// is a script, so importing it would run the whole batch, and the number that
// has to hold is the one the artefact was actually built under. It travels with
// the artefact for that reason.
const ceiling = index.unknownCeilingPercent
ok(
  'the content publishes the ceiling it was built under',
  typeof ceiling === 'number' && ceiling > 0 && ceiling <= 5,
  `unknownCeilingPercent: ${ceiling}`
)
ok(
  'the unknown share is under the ceiling',
  index.counts.unknownPercent < ceiling && index.counts.unknown > 0,
  `${index.counts.unknown} of ${index.counts.rooms} = ${index.counts.unknownPercent}%, ceiling ${ceiling}% (a zero here would mean the residue list stopped being written)`
)

// ------------------------------------------------ 5. total vocabularies

ok(
  'every ground kind a record carries is one of the declared kinds',
  [...groundSeen].every((kind) => GROUND_KINDS.includes(kind)) && groundSeen.size > 5,
  `${groundSeen.size} distinct: ${[...groundSeen].sort().join(', ')}`
)
ok(
  'every rule a record names is one of the declared rules',
  [...ruleSeen].every((rule) => GROUND_RULES.includes(rule)) && ruleSeen.size > 2,
  `${ruleSeen.size} distinct: ${[...ruleSeen].sort().join(', ')}`
)
ok(
  "every room's block kind is the one its ground kind maps to",
  blockAgrees === contentRooms && contentRooms >= MIN_ROOMS,
  `${blockAgrees} of ${contentRooms}`
)
ok(
  'the ground-to-block map is total over the ground vocabulary',
  GROUND_KINDS.every((kind) => BLOCK_KINDS.includes(blockKindFor(kind))),
  `${GROUND_KINDS.length} ground kinds -> ${BLOCK_KINDS.length} block kinds`
)

console.log(`\n${pass + fail} checked, ${fail} failed`)
if (fail) process.exit(1)
console.log('all passed')
